sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiValues = {
        'buttonData': []
    };

    try {
        // Initialize counters
        var totalCount = 0;
        var totalCompletedCount = 0;

        // Process system property "Mark as complete button property"
        var sysPropertyValue = gs.getProperty('Mark as complete button property');
        if (sysPropertyValue) {
            try {
                var propData = JSON.parse(sysPropertyValue);

                // Add property data to our results
                for (var btnId in propData) {
                    if (propData.hasOwnProperty(btnId)) {
                        // Convert property value to boolean
                        var btnState = propData[btnId] === true || propData[btnId] === 'true';

                        totalCount += 1;
                        if (btnState) {
                            totalCompletedCount += 1;
                        }

                        kpiValues.buttonData.push({
                            "buttonId": btnId,
                            "buttonState": btnState
                        });
                    }
                }
            } catch (parseErr) {
                gs.error("Error parsing system property 'Mark as complete button property': " + parseErr.toString());
            }
        } else {
            gs.info("System property 'Mark as complete button property' not found or empty.");
        }

        // Add summary statistics
        // kpiValues['summary'] = {
        //     "total": totalCount,
        //     "completed": totalCompletedCount,
        //     "incompleted": totalCount - totalCompletedCount
        // };

        // Add dial chart data
        var completionPercentage = totalCount > 0 ? (totalCompletedCount/totalCount)*100 : 0;
        kpiValues['dialChart'] = [
            {
                "data": [
                    {
                        "value": completionPercentage,
                        "change": 20,
                        "changePercent": 10
                    }
                ],
                "metadata": {
                    "eventData": {
                        "indicatorSysid": "fb007202d7130100b96d45a3ce6103b4"
                    },
                    "dataSourceLabel": "Number of open incidents",
                    "filterQuery": "opened_atONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()^ORopened_at<javascript:gs.beginningOfToday()^resolved_atISEMPTY^ORresolved_at>javascript:gs.endOfToday()^state!=8",
                    "aggregate": {
                        "fieldType": "percentage"
                    },
                    "format": {
                        "unitFormat": "{0}%",
                        "frequency": "daily",
                        "precision": "0"
                    }
                }
            }
        ];

        // Log the transformed data for verification
        // gs.info("Transformed Data: " + JSON.stringify(kpiValues, null, 2));

    } catch (e) {
        // Handle and log errors
        gs.error("Error in transform script: " + e.toString());
        return {
            'error': e.toString()
        };
    }

    // Return the transformed data
    return kpiValues;
}
